#!/bin/bash
# Auto-generated launcher: ships synth_verify to Olvi, launches GPU srun job.
set -e
JDIR=/data/hvardhan2/jobs/synth
mkdir -p $JDIR/synth_verify $JDIR/logs
cd $JDIR
echo '' | base64 -d > synth_verify/__init__.py
echo '' | base64 -d > synth_verify/tools.py
echo '' | base64 -d > synth_verify/task.py
echo '' | base64 -d > synth_verify/stream.py
echo '' | base64 -d > synth_verify/agent_harness.py
echo '' | base64 -d > synth_verify/run_cond.py
echo '' | base64 -d > synth_verify/build_dataset.py
echo '' | base64 -d > synth_verify/train_lora.py
cat > job_pilot.sh <<'JOBEOF'
#!/bin/bash
set -x
export HF_HOME=/data/hvardhan2/hf-cache
export PATH="$HOME/.local/bin:$PATH"
cd /data/hvardhan2/jobs/synth
/data/hvardhan2/vllm-venv/bin/vllm serve Qwen/Qwen3-8B --port 8001 --max-model-len 8192 > vllm_pilot.log 2>&1 &
VPID=$!
echo "vllm pid $VPID, waiting for health"
for i in $(seq 1 90); do
  if curl -s http://localhost:8001/health > /dev/null 2>&1; then echo "healthy after $((i*10))s"; break; fi
  sleep 10
done
curl -s http://localhost:8001/v1/models | head -c 300; echo
python3 synth_verify/run_cond.py --condition 1 --n 10 --seed 0 \
  --api-base http://localhost:8001/v1 --model Qwen/Qwen3-8B \
  --log logs/cond1_pilot.jsonl > logs/cond1_pilot.out 2>&1
echo "PILOT rc=$?"
kill $VPID 2>/dev/null
echo "=== PILOT JOB DONE ==="

JOBEOF
chmod +x job_pilot.sh
setsid nohup srun --gres=gpu:1 --cpus-per-task=8 --mem=96G --time=01:00:00 bash $JDIR/job_pilot.sh > $JDIR/pilot_srun.out 2>&1 < /dev/null &
sleep 8; echo "launched:"; squeue -u hvardhan2
